/**
 * kit check sdk: every OpenAPI contract of the repository has an SDK generated by @saasreport/forge, current and untouched.
 *
 * Fails when
 *   missing      an OpenAPI contract (kit.canon.json contracts of type openapi, or kit.sdk.json `contracts` globs) has no
 *                target in kit.sdk.json, or kit.sdk.json itself is missing while the repository has OpenAPI contracts;
 *                or a target's output directory or its forge.manifest.json is missing
 *   contract     the contract cannot be generated (not 3.1, no summary, no 2xx, Forge rejects it)
 *   stale        the contract changed since generation (its sha256 differs from the manifest's), or the generator did
 *                (regenerate-and-diff: a file differs from what kit sdk generate writes now)
 *   hand-edited  a generated file differs from the sha256 the manifest pinned, a file was added to or removed from
 *                the output directory
 *   duplicate    a hand-written client: code under `scan` that calls fetch() on a contract path, or a copy of a
 *                generated file outside its output directory; unless kit.sdk.json `allow` lists it with a reason
 *   naming       a target's name or CLI is not the project's own prefix (naming constitution)
 *
 * checkSdk(root, { canon, registry, validate }) → { ok, summary, problems: [{ file, problem }] }
 *   validate(value, schemaName) → [message]: the kit's validator over the bundled schemas (sdk-config, sdk-manifest)
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { generateTarget, listFiles, loadContract, MANIFEST_FILE, MARK, sha256 } from "./generate.js";
import { expandFiles, matchesAny, readText } from "./files.js";

export const CONFIG_FILE = "kit.sdk.json";
const P = (file, problem) => ({ file, problem });
const toTemplate = (p) => p.replace(/\$\{[^}]*\}/g, "{}").replace(/\{[^}]*\}/g, "{}");

/** kit.sdk.json, if any: { config, problems }. */
export function loadSdkConfig(root, { validate } = {}) {
  const file = join(root, CONFIG_FILE);
  if (!existsSync(file)) return { config: null, problems: [] };
  let config;
  try { config = JSON.parse(readFileSync(file, "utf8")); } catch (e) { return { config: null, problems: [P(CONFIG_FILE, `not JSON: ${e.message}`)] }; }
  const problems = [];
  if (validate) for (const m of validate(config, "sdk-config")) problems.push(P(CONFIG_FILE, `sdk-config: ${m}`));
  return { config, problems };
}

/** The OpenAPI contracts the repository declares: kit.canon.json openapi contracts + kit.sdk.json `contracts` globs. */
export function declaredContracts(root, canon, config) {
  const set = new Set((canon?.contracts || []).filter((c) => c.type === "openapi").map((c) => c.contract));
  for (const f of expandFiles(root, config?.contracts || [])) set.add(f);
  return [...set].sort();
}

/** The names a project may give its SDK: its registry key, prefix and short prefix (without the dash). */
export function ownNames(project, registry) {
  if (project === "kit") return ["kit"];
  const p = registry?.projects?.find((x) => x.key === project);
  if (!p) return [];
  return [...new Set([p.key, p.prefix?.replace(/-$/, ""), p.short?.replace(/-$/, "")].filter(Boolean))];
}
export const ownedBy = (name, names) => names.some((n) => name === n || name.startsWith(`${n}-`));

/** A template path ("/api/forms/{}") as a regular expression: {} matches one segment. */
const pattern = (t) => new RegExp(`^${t.split("{}").map((x) => x.replace(/[.*+?^$()|[\]\\{}]/g, "\\$&")).join("[^/]+")}/?$`);

/** fetch() calls whose URL argument is a path of the contract: [{ line, path (the code's, {} for an expression), contract, text }]. */
export function fetchCalls(src, paths) {
  const out = [];
  const lines = src.split("\n");
  const re = /\bfetch\s*\(\s*(`(?:\\.|[^`])*`|"(?:\\.|[^"])*"|'(?:\\.|[^'])*'|new\s+URL\s*\(\s*(`(?:\\.|[^`])*`|"(?:\\.|[^"])*"|'(?:\\.|[^'])*'))/g;
  for (const m of src.matchAll(re)) {
    const raw = (m[2] || m[1]).slice(1, -1);
    const url = toTemplate(raw).replace(/(\{\})+/g, "{}").split("?")[0].replace(/^https?:\/\/[^/]+/, "").replace(/^\{\}(?=\/)/, "");
    const hit = url.startsWith("/") ? paths.find((p) => p === url || p === url.replace(/\/$/, "") || pattern(p).test(url) || pattern(url).test(p)) : undefined;
    if (hit) out.push({ line: src.slice(0, m.index).split("\n").length, path: url.replace(/\/$/, "") || "/", contract: hit, text: lines[src.slice(0, m.index).split("\n").length - 1].trim().slice(0, 120) });
  }
  return out;
}

/** The full check. */
export async function checkSdk(root, { canon = null, registry = null, validate = null } = {}) {
  const problems = [];
  const { config, problems: cfgProblems } = loadSdkConfig(root, { validate });
  problems.push(...cfgProblems);
  const contracts = declaredContracts(root, canon, config);
  if (!config) {
    if (contracts.length) problems.push(P(CONFIG_FILE, `missing: the repository has ${contracts.length} OpenAPI contract${contracts.length === 1 ? "" : "s"} (${contracts.join(", ")}) and no Forge-generated SDK; declare targets in kit.sdk.json and run kit sdk generate (docs/SDK.md)`));
    return { ok: !problems.length, configured: false, checked: 0, summary: contracts.length ? "no kit.sdk.json" : "no OpenAPI contracts", problems };
  }
  const targets = config.targets || [];
  const project = canon?.project || config.project;
  const names = ownNames(project, registry);

  // missing: every contract has a target
  for (const c of contracts) if (!targets.some((t) => t.contract === c)) problems.push(P(c, `OpenAPI contract without a Forge-generated SDK: add a target to ${CONFIG_FILE} and run kit sdk generate`));
  const seen = new Set();
  let ops = 0, files = 0;
  for (const t of targets) {
    if (seen.has(t.name)) problems.push(P(CONFIG_FILE, `target name ${t.name} is used twice`));
    seen.add(t.name);
    if (names.length && !ownedBy(t.name, names)) problems.push(P(CONFIG_FILE, `target ${t.name}: not ${project}'s own prefix (${names.join(", ")}): naming constitution, docs/NAMING.md`));
    if (names.length && t.cli && !ownedBy(t.cli, names)) problems.push(P(CONFIG_FILE, `target ${t.name}: CLI ${t.cli} is not ${project}'s own prefix (${names.join(", ")})`));
    const gen = await generateTarget(root, t, targets);
    for (const p of gen.problems) problems.push(P(t.contract, p.replace(`${t.contract}: `, "")));
    if (gen.problems.length) continue;
    ops += gen.operations;
    const out = t.out.replace(/\/$/, "");
    const manifestFile = join(root, out, MANIFEST_FILE);
    if (!existsSync(manifestFile)) { problems.push(P(`${out}/${MANIFEST_FILE}`, `missing: no generated SDK for ${t.contract} (run kit sdk generate)`)); continue; }
    let manifest;
    try { manifest = JSON.parse(readFileSync(manifestFile, "utf8")); } catch (e) { problems.push(P(`${out}/${MANIFEST_FILE}`, `not JSON: ${e.message}`)); continue; }
    if (validate) for (const m of validate(manifest, "sdk-manifest")) problems.push(P(`${out}/${MANIFEST_FILE}`, `sdk-manifest: ${m}`));
    const contractChanged = manifest.contract?.sha256 !== gen.manifest.contract.sha256;
    if (contractChanged) problems.push(P(out, `stale: ${t.contract} changed since the SDK was generated (run kit sdk generate)`));
    const pinned = new Map((manifest.files || []).map((f) => [f.path, f.sha256]));
    const want = new Map(gen.files.map((f) => [f.path, f.content]));
    const have = listFiles(join(root, out));
    files += have.length;
    for (const f of have) {
      if (!want.has(f)) { problems.push(P(`${out}/${f}`, "not generated: added by hand to the generated SDK (remove it; generated output only)")); continue; }
      const text = readFileSync(join(root, out, f), "utf8");
      if (f !== MANIFEST_FILE && pinned.has(f) && sha256(text) !== pinned.get(f)) problems.push(P(`${out}/${f}`, "hand-edited: differs from the sha256 in forge.manifest.json (never edit generated files: change the contract, run kit sdk generate)"));
      else if (!contractChanged && text !== want.get(f)) problems.push(P(`${out}/${f}`, "stale: differs from what kit sdk generate writes now (the generator changed: run kit sdk generate)"));
    }
    for (const f of want.keys()) if (!have.includes(f)) problems.push(P(`${out}/${f}`, "missing from the generated SDK (run kit sdk generate)"));
  }

  // duplicates: hand-written clients outside the generated directories
  const outs = targets.map((t) => t.out.replace(/\/$/, ""));
  const scan = config.scan ?? canon?.hardcoding?.paths ?? ["src"];
  // the default scan is the code the hardcoding scan covers; tests are out of its scope everywhere (they probe a server directly)
  const skip = [...(config.scan ? [] : ["**/test/**", "**/tests/**", "**/__tests__/**", "**/*.test.*"]), ...(config.exclude || [])];
  const marker = `// Generated by ${MARK} transformer`;
  const allow = config.allow || [];
  const used = new Set();
  const contractPaths = [];
  for (const t of targets) {
    try {
      const { doc } = loadContract(root, t.contract);
      for (const p of Object.keys(doc.paths || {})) contractPaths.push({ path: toTemplate(p), out: t.out });
    } catch { /* an unreadable contract is already a problem reported above */ }
  }
  const paths = [...new Set(contractPaths.map((c) => c.path))].sort((a, b) => b.length - a.length);
  const generatedShas = new Set();
  for (const o of outs) for (const f of listFiles(join(root, o))) if (f !== MANIFEST_FILE) generatedShas.add(sha256(readFileSync(join(root, o, f), "utf8")));
  for (const f of expandFiles(root, scan).filter((x) => /\.(m?js|cjs|ts|mts|tsx|jsx)$/.test(x) && !outs.some((o) => x === o || x.startsWith(`${o}/`)) && !matchesAny(x, skip))) {
    const src = readText(root, f);
    const copy = src.includes(marker) || generatedShas.has(sha256(src));
    const calls = fetchCalls(src, paths);
    const hits = [...(copy ? [{ line: 1, path: "*", text: "a copy of a generated SDK file" }] : []), ...calls];
    for (const h of hits) {
      const a = allow.find((e) => e.file === f && e.path === h.path);
      if (a) { used.add(a); continue; }
      const out = contractPaths.find((c) => c.path === (h.contract || h.path))?.out ?? outs[0];
      problems.push(P(`${f}:${h.line}`, h.path === "*" ? `duplicate: a copy of a generated SDK file outside ${outs.join(", ")} (import the generated SDK instead)` : `duplicate: hand-written client of ${h.path} (\`${h.text}\`): use the generated SDK in ${out}, or list it in ${CONFIG_FILE} allow with a reason`));
    }
  }
  for (const a of allow) {
    if (!used.has(a)) problems.push(P(CONFIG_FILE, `stale allow entry (matches nothing; remove it): ${a.file} ${a.path}`));
  }
  return {
    ok: !problems.length, configured: true, checked: targets.length,
    summary: `${targets.length} target${targets.length === 1 ? "" : "s"} for ${contracts.length} contract${contracts.length === 1 ? "" : "s"}, ${ops} operations, ${files} generated files; ${allow.length} allowed client${allow.length === 1 ? "" : "s"}`,
    problems,
  };
}
